/usr/bin/bash -lc "python3 - <<'PY'
import json, pathlib, sys
plan=json.load(open('.exp_agent/round_plan_02.json'))
report=json.load(open('.exp_agent/round_completion_02.json'))
expected=[]
for rule in plan['rules']:
  for f in rule['files']:
    for loc in f['locations']:
      expected.append((rule['rule'],f['relative_path'],loc['line'],loc['column']))
actual=[]
for e in report['entity_repairs']:
  assert e['status']=='repaired', e
  for loc in e['locations']:
    actual.append((e['rule'],e['relative_path'],loc['line'],loc['column']))
print('expected_locations',len(expected),'actual_locations',len(actual),'exact_match',sorted(expected)==sorted(actual))
print('expected_groups',sum(len(r['files']) for r in plan['rules']),'actual_groups',len(report['entity_repairs']))
assert sorted(expected)==sorted(actual)
assert report['unresolved_external']==[]
for r in plan['rules']:
  assert r['rule'] in report['selected_rules']
  assert len(report['consulted_specs'][r['rule']]) >= 2
for e in report['entity_repairs']:
  for k in ('owning_entities','invariants','evidence','transformation'):
    assert e[k] and all(e[k])
PY"
